{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "title": "Niterói's land: summer temperature against park area within reach",
  "layer": [
    {
      "mark": {
        "type": "point",
        "filled": true,
        "opacity": 0.6
      },
      "encoding": {
        "x": {
          "field": "park area within about 500 m (km²)",
          "type": "quantitative",
          "title": "Park area within about 500 m (km²)"
        },
        "y": {
          "field": "summer temperature, 2020 to 2024 (°C)",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "Mean summer surface temperature, 2020 to 2024 (°C)"
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "color": "#d62728",
        "strokeWidth": 2
      },
      "transform": [
        {
          "regression": "summer temperature, 2020 to 2024 (°C)",
          "on": "park area within about 500 m (km²)"
        }
      ],
      "encoding": {
        "x": {
          "field": "park area within about 500 m (km²)",
          "type": "quantitative"
        },
        "y": {
          "field": "summer temperature, 2020 to 2024 (°C)",
          "type": "quantitative"
        }
      }
    }
  ]
}
